content.text:
{
  "name": "PWM输入传感器",
  "name_en": "PWM Input Sensor",
  "manufacturer": "Yoctopuce",
  "description": "用于读取和配置 Yoctopuce 的 PWM 输入通道，可测量占空比、频率、脉宽、周期和脉冲计数，并可设置上报模式、去抖时间等参数。适合在实验室中监测来自编码器、脉冲源或其他 PWM 信号设备的数字时序信号。",
  "description_en": "A Yoctopuce PWM input channel used to read and configure PWM signal measurements, including duty cycle, frequency, pulse width, period, and pulse count. It also supports report mode and debounce configuration for laboratory monitoring of digital timing signals from encoders, pulse sources, or other PWM-generating equipment.",
  "actions": [
    {
      "action_name": "auto-set_unit",
      "description": "设置测量单位",
      "description_en": "Set the measurement unit."
    },
    {
      "action_name": "auto-set_pulseCounter",
      "description": "设置脉冲计数值",
      "description_en": "Set the pulse counter value."
    },
    {
      "action_name": "auto-set_pwmReportMode",
      "description": "设置 PWM 上报参数模式",
      "description_en": "Set the PWM report parameter mode."
    },
    {
      "action_name": "auto-set_debouncePeriod",
      "description": "设置去抖时间",
      "description_en": "Set the debounce period."
    },
    {
      "action_name": "auto-resetCounter",
      "description": "重置脉冲计数器",
      "description_en": "Reset the pulse counter."
    },
    {
      "action_name": "auto-nextPwmInput",
      "description": "枚举下一个可用的 PWM 输入通道",
      "description_en": "Enumerate the next available PWM input channel."
    }
  ],
  "tag_hints": [
    "PWM signal measurement",
    "duty cycle sensing",
    "frequency measurement",
    "pulse width measurement",
    "pulse counting",
    "digital timing input",
    "Yoctopuce module"
  ]
}

